20	background:linear-gradient(90deg,var(--rail),#27324a,var(--rail))}
21	.bus::after{content:"";position:absolute;top:0;left:-30%;width:30%;height:100%;
22	background:linear-gradient(90deg,transparent,var(--teal),transparent);animation:pulse 3.2s linear infinite}
23	@keyframes pulse{to{left:130%}}
24	h2{font-family:var(--mono);font-size:12.5px;letter-spacing:.16em;text-transform:uppercase;
25	color:var(--teal);margin:38px 0 12px;display:flex;align-items:center;gap:10px}
