29	.row .num{font-family:var(--mono);font-size:13px;color:var(--faint);flex:0 0 auto;min-width:34px}
30	.row a.main{color:var(--ink);text-decoration:none;font-weight:600;flex:1}
31	.row a.main:hover{color:var(--teal)}
32	.row .drill{flex:0 0 auto;font-family:var(--mono);font-size:12.5px;text-decoration:none;
33	color:var(--indigo);border:1px solid #34347a;border-radius:20px;padding:5px 12px}
34	.row .drill:hover{background:color-mix(in srgb,var(--indigo) 14%,transparent)}
35	.row .none{flex:0 0 auto;font-family:var(--mono);font-size:11.5px;color:var(--faint)}
36	.row.lone .num{color:var(--indigo)}
37	.empty{color:var(--faint);font-size:15px;font-style:italic;padding:8px 0}
38	footer{margin-top:40px;color:var(--faint);font-family:var(--mono);font-size:11.5px}
39	:focus-visible{outline:2px solid var(--teal);outline-offset:2px}
40	@media(prefers-reduced-motion:reduce){.bus::after{display:none}}
